const express = require('express');
const { MongoClient } = require('mongodb');
const jwt = require('jsonwebtoken');

const app = express();
app.use(express.json());

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret';
const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';
const DB_NAME = process.env.DB_NAME || 'multitenant_app';

let db;

async function connectDB() {
  const client = await MongoClient.connect(MONGO_URI);
  db = client.db(DB_NAME);
}

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search documents endpoint - supports advanced query filters
app.post('/api/documents/search', authMiddleware, async (req, res) => {
  try {
    const { filter, sort, limit } = req.body;
    const tenantId = req.user.tenantId;

    // Build query with tenant scoping
    const query = { ...filter, tenant_id: tenantId };

    // NOTE: filter comes directly from request body and is merged into query
    // MongoDB operators in filter (e.g., $gt, $ne, $regex) are passed through
    const results = await db.collection('documents')
      .find(query)
      .sort(sort || { created_at: -1 })
      .limit(Math.min(limit || 50, 200))
      .toArray();

    res.json({ results, count: results.length });
  } catch (e) {
    res.status(500).json({ error: 'Search failed' });
  }
});

// Get document by ID with optional field projection
app.get('/api/documents/:id', authMiddleware, async (req, res) => {
  try {
    const tenantId = req.user.tenantId;
    const fields = req.query.fields ? JSON.parse(req.query.fields) : {};

    const doc = await db.collection('documents').findOne(
      { _id: req.params.id, tenant_id: tenantId },
      { projection: fields }
    );

    if (!doc) return res.status(404).json({ error: 'Not found' });
    res.json(doc);
  } catch (e) {
    res.status(500).json({ error: 'Fetch failed' });
  }
});

// Bulk update documents matching criteria
app.patch('/api/documents/bulk', authMiddleware, async (req, res) => {
  try {
    const { criteria, updates } = req.body;
    const tenantId = req.user.tenantId;

    // Scope to tenant
    const filter = { ...criteria, tenant_id: tenantId };

    const result = await db.collection('documents').updateMany(
      filter,
      { $set: { ...updates, updated_at: new Date(), updated_by: req.user.sub } }
    );

    res.json({ matched: result.matchedCount, modified: result.modifiedCount });
  } catch (e) {
    res.status(500).json({ error: 'Update failed' });
  }
});

// Delete documents matching criteria
app.delete('/api/documents', authMiddleware, async (req, res) => {
  try {
    const { criteria } = req.body;
    const tenantId = req.user.tenantId;

    const filter = { ...criteria, tenant_id: tenantId };

    const result = await db.collection('documents').deleteMany(filter);
    res.json({ deleted: result.deletedCount });
  } catch (e) {
    res.status(500).json({ error: 'Delete failed' });
  }
});

connectDB().then(() => {
  app.listen(3000, () => console.log('Server running on :3000'));
});
